static inline void /* <=== add_gray_list */ 
add_gray_list(mrb_state *mrb, mrb_gc *gc, struct RBasic *obj)
{
#ifdef MRB_GC_STRESS
  if (obj->tt > MRB_TT_MAXDEFINE) {
    abort();
  }
#endif
  paint_gray(obj);
  obj->gcnext = gc->gray_list;
  gc->gray_list = obj;
}

MRB_API void /* <=== mrb_gc_mark */ 
mrb_gc_mark(mrb_state *mrb, struct RBasic *obj)
{
  if (obj == 0) return;
  if (!is_white(obj)) return;
  mrb_assert((obj)->tt != MRB_TT_FREE);
  add_gray_list(mrb, &mrb->gc, obj);
}

MRB_INLINE mrb_value mrb_nil_value(void) /* <=== mrb_nil_value */ 
{
  mrb_value v;
  SET_NIL_VALUE(v);
  return v;
}

